import {getOrders,sendChat,customers,DATA_VERSION} from './data.js';
import {END,categories,analyzeOrder,summarizeOrders,filterOrders,seriesFor,riskRank} from './metrics.js';
import {esc,money,num,pct,pp,signed,tone,badge,icon,empty} from './ui.js';
import {renderTrend,renderCostVariance} from './charts.js';

const state={orders:[],loading:true,error:null,route:'monitor',orderId:null,search:'',customer:'',status:'生产中',risk:'',asOf:END,period:16,page:1,sort:'risk',mode:'cumulative',day:END,inspected:null,chatScope:'all',chatDraft:'',chatStatus:''};
const app=document.querySelector('#app');
const titles={monitor:['订单动态监测','持续跟踪生产变化，让每一笔订单的利润可见。'],order:['订单利润分析','从每日变化到成本明细，追踪利润偏差。'],data:['订单详细数据','核查生产记录、成本来源与每一步计算依据。'],ai:['AI 订单助手','围绕订单和生产数据，预留智能分析入口。']};
const option=(value,label,current)=>`<option value="${esc(value)}" ${String(value)===String(current)?'selected':''}>${esc(label)}</option>`;
const selectedOrder=()=>state.orders.find(o=>o.id===state.orderId);
const filtered=()=>filterOrders(state.orders,state);
const progress=a=>`<div class="progress"><div class="progress-track"><i style="width:${Math.min(100,a.progress*100)}%"></i></div>${pct(a.progress)}</div>`;
const costItems=a=>categories.map(name=>{const expected=a.comparable?a.revenue*(1-a.order.planRate)*(a.order.planShares[name]/.8):null;return {name,expected,actual:a.costs[name],delta:expected!==null&&a.costs[name]!==null?a.costs[name]-expected:null};});
function mainCause(a){if(!a.comparable)return a.risk==='数据不足'?'生产或成本记录待补齐':'预期基线待确认';const c=costItems(a).sort((x,y)=>y.delta-x.delta)[0];return c.delta>0?c.name+'成本偏高':'当前成本低于预期';}
function parseRoute(){const [route,id]=location.hash.slice(1).split('/');state.route=['monitor','order','data','ai'].includes(route)?route:'monitor';state.orderId=id?decodeURIComponent(id):null;if(state.route==='data'&&!state.orderId)state.orderId=state.orders[0]?.id;if(state.route==='ai'&&state.orderId)state.chatScope=state.orderId;}
function go(hash){if(location.hash===hash){parseRoute();render();}else location.hash=hash;}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function shell(content){const [title,sub]=titles[state.route];return `<aside class="sidebar"><a class="brand" href="#monitor" aria-label="企盈智擎首页"><span class="brand-mark"></span><span>企盈智擎</span></a><div class="brand-sub">QIYING INTELLIGENCE</div><div class="nav-label">工作空间</div><nav class="nav" aria-label="主要导航"><a href="#monitor" class="${['monitor','order'].includes(state.route)?'active':''}" ${['monitor','order'].includes(state.route)?'aria-current="page"':''} title="订单监测">${icon('chart')}<span>订单监测</span></a><a href="#data" class="${state.route==='data'?'active':''}" ${state.route==='data'?'aria-current="page"':''} title="订单详细数据">${icon('file')}<span>订单详细数据</span></a><a href="#ai" class="${state.route==='ai'?'active':''}" ${state.route==='ai'?'aria-current="page"':''} title="AI 对话">${icon('chat')}<span>AI 对话</span><span class="tiny-label">预留</span></a></nav><div class="side-bottom"><div class="side-note"><strong>${icon('layers')} 框架演示工作区</strong>所有订单均为合成数据<br>用于团队体验与功能讨论</div><div class="side-user"><div class="avatar">企</div><div><strong>项目工作台</strong><small>开发预览 · v0.1</small></div></div></div></aside><main class="main" id="main"><header class="topbar"><div><div class="eyebrow">ORDER INTELLIGENCE / ${state.route==='monitor'?'OVERVIEW':state.route.toUpperCase()}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="top-actions"><span class="demo-pill">合成演示数据</span><input class="control date-control" type="date" id="asOf" aria-label="数据截至日期" min="2026-10-01" max="${END}" value="${state.asOf}"><button class="button primary" data-action="refresh">${icon('refresh')}<span>刷新数据</span></button></div></header>${content}<footer class="bottomline"><span>${icon('info')}已发生利润与预计完工利润分开核算</span><a href="#ai" class="ai-quick">${icon('spark')}询问 AI · 接口待接入 ${icon('chevron')}</a></footer></main>`;}
function stat(label,value,foot,ico,color='',valueClass='',unit=''){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}">${icon(ico)}</span></div><div class="stat-value ${valueClass}">${value}${unit?`<em>${unit}</em>`:''}</div><p class="stat-foot"><span class="dot"></span>${foot}</p></article>`;}
function filters(){return `<section class="filters" aria-label="筛选订单"><select class="control" id="customer" aria-label="客户">${option('','全部客户',state.customer)}${customers.map(c=>option(c,c,state.customer)).join('')}</select><select class="control" id="status" aria-label="订单状态">${['','生产中','已完工'].map(s=>option(s,s||'全部状态',state.status)).join('')}</select><select class="control" id="risk" aria-label="风险等级">${['',...Object.keys(riskRank)].map(s=>option(s,s||'全部风险',state.risk)).join('')}</select><select class="control" id="period" aria-label="趋势时间范围">${option(7,'近 7 天趋势',state.period)}${option(16,'近 16 天趋势',state.period)}${option(30,'近 30 天趋势',state.period)}</select><label class="search-box">${icon('search')}<input class="control" type="search" id="search" placeholder="搜索订单号、产品或客户" value="${esc(state.search)}" aria-label="搜索订单"></label><button class="filter-reset" data-action="reset">重置筛选</button></section>`;}
const legend=()=>'<div class="legend"><span><i></i>实际</span><span><i class="dashed"></i>同期预期</span></div>';
function monitoring(){
 const orders=filtered(),s=summarizeOrders(orders,state.asOf);const sorted=[...s.analyses].sort((a,b)=>state.sort==='delta'?(a.delta??Infinity)-(b.delta??Infinity):state.sort==='id'?a.order.id.localeCompare(b.order.id):(riskRank[a.risk]-riskRank[b.risk])||((a.delta??0)-(b.delta??0)));
 const alerts=sorted.filter(a=>['严重','重点','注意'].includes(a.risk)).slice(0,3);const pages=Math.max(1,Math.ceil(sorted.length/6));state.page=Math.min(state.page,pages);const pageRows=sorted.slice((state.page-1)*6,state.page*6);
 return `${filters()}<section class="cards" aria-label="订单汇总">${stat('在产订单',s.active,'当前筛选共 '+s.count+' 笔订单','file','','','笔')}${stat('累计生产毛利',money(s.profit),s.known+' 笔具备实际核算数据','wallet','green')}${stat('较同期预期差额',signed(s.delta),s.comparable+' 笔可比 · '+s.excluded+' 笔未纳入','down','red',tone(s.delta))}${stat('需关注订单',s.alerts,s.severe+' 笔严重偏离预期','alert','amber','','笔')}</section><section class="overview-grid"><article class="panel"><div class="panel-head"><div><h2>利润趋势</h2><p>同数量 · 同期间 · 累计生产毛利</p></div>${legend()}</div><div class="chart-wrap">${renderTrend(seriesFor(orders,state.asOf,state.period))}</div>${state.inspected?dayResult(orders):''}<div class="chart-foot"><span>${icon('clock')}截至 ${state.asOf} · 累计起点为各订单开工日</span><span>点击曲线节点查看当日汇总</span></div></article><article class="panel"><div class="panel-head"><h2>优先关注 <span class="count">${s.alerts}</span></h2><button class="link" data-action="alerts">查看严重订单</button></div><div class="attention-list">${alerts.length?alerts.map(a=>`<a class="attention-item" href="#order/${a.order.id}"><div class="attention-icon">${icon('alert')}</div><div class="body"><strong>${a.order.id}</strong><p>${mainCause(a)} · ${a.order.customer}</p><div class="amount negative">${signed(a.delta)} <small>较预期</small></div></div><div>${badge(a.risk)}</div>${icon('chevron','chev')}</a>`).join(''):empty('暂无已确认的利润偏离',s.excluded?'仍有订单缺少可比数据。':'当前筛选范围内状态平稳。')}</div><div class="panel-footer"><span>成本偏差线索，原因待核验</span><a href="#data">核查明细 →</a></div></article></section><section class="panel"><div class="table-top"><h2>订单监测 <span class="count">${s.count} 笔订单</span></h2><div class="table-tools"><span class="muted" style="font-size:10px">按风险优先跟进</span><select class="control" id="sort" aria-label="订单排序">${option('risk','风险优先',state.sort)}${option('delta','利润差额从低到高',state.sort)}${option('id','订单号升序',state.sort)}</select></div></div>${pageRows.length?`<div class="table-wrap"><table><thead><tr><th>订单 / 产品</th><th>客户</th><th>生产进度</th><th>预期毛利率</th><th>当前毛利率</th><th>较预期偏差</th><th>较昨日变化</th><th>风险等级</th><th>操作</th></tr></thead><tbody>${pageRows.map(a=>`<tr><td><strong>${a.order.id}</strong><small>${a.order.product}</small></td><td>${a.order.customer}</td><td>${progress(a)}</td><td>${pct(a.order.planRate)}</td><td class="${a.rate<0?'negative':''}">${pct(a.rate)}</td><td class="${tone(a.deviation)}">${pp(a.deviation)}</td><td class="${tone(a.yesterdayChange)}">${pp(a.yesterdayChange)}</td><td>${badge(a.risk)}</td><td><a class="link" href="#order/${a.order.id}">查看分析</a></td></tr>`).join('')}</tbody></table></div>`:empty()}<div class="table-bottom"><span>共 ${s.count} 笔 · ${s.count?((state.page-1)*6+1):0}–${Math.min(state.page*6,s.count)} 笔 · pp 表示百分点</span><div class="pagination"><button class="page-btn" data-page="${state.page-1}" aria-label="上一页" ${state.page===1?'disabled':''}>${icon('back')}</button>${Array.from({length:pages},(_,i)=>`<button class="page-btn ${state.page===i+1?'active':''}" data-page="${i+1}" aria-label="第 ${i+1} 页">${i+1}</button>`).join('')}<button class="page-btn" data-page="${state.page+1}" aria-label="下一页" ${state.page===pages?'disabled':''}>${icon('chevron')}</button></div></div></section><details class="help-block"><summary>计算口径与风险规则</summary>实际毛利按已完成产量对应的演示收入减生产成本计算。相对毛利下降≤10%正常，≤20%注意，≤30%重点，超过30%严重；预期≤0不使用相对评级。缺数据与缺基线独立提示。汇总毛利率按收入加权，不直接平均订单毛利率。累计趋势各日期纳入订单数可能随数据完整性变化，点击节点可核查。</details>`;
}
function dayResult(orders){const s=summarizeOrders(orders,state.inspected);return `<div class="date-result">${state.inspected} · 累计可比毛利 ${money(s.compareProfit)} · 预期 ${money(s.expected)} · ${s.comparable} 笔可比 <button class="link" data-action="clear-day">收起</button></div>`;}
function detail(){const o=selectedOrder();if(!o)return missingOrder();const a=analyzeOrder(o,state.asOf),items=costItems(a);const day=o.daily.find(d=>d.date===state.day&&d.date<=state.asOf);const da=day?analyzeOrder({...o,daily:[day]},state.day):null;
 return `<div class="breadcrumbs"><a href="#monitor">订单监测</a>${icon('chevron')}<span>订单分析</span></div><div class="detail-heading"><h1>${o.id}</h1>${badge(a.risk)}<span class="demo-pill">演示订单</span></div><div class="order-meta"><span>产品<b>${o.product}</b></span><span>客户<b>${o.customer}</b></span><span>订单数量<b>${num(o.quantity)} 双</b></span><span>计划周期<b>${o.start} — ${o.end}</b></span><span>状态<b>${o.status}</b></span></div><section class="cards">${stat('当前累计生产毛利',money(a.profit),'演示收入减已归集生产成本','wallet','green',a.profit<0?'negative':'')}${stat('当前累计毛利率',pct(a.rate),'预期毛利率 '+pct(o.planRate),'chart')}${stat('较同期预期差额',signed(a.delta),'毛利率偏差 '+pp(a.deviation),'down','red',tone(a.delta))}${stat('生产进度',pct(a.progress),num(a.quantity)+' / '+num(o.quantity)+' 双','layers')}</section><div class="detail-grid"><section class="panel"><div class="panel-head"><div><h2>每日利润变化</h2><p>${state.mode==='daily'?'当日发生额':'开工日至当前日期累计'} · 点击节点核查当天数据</p></div><div class="segmented"><button data-mode="cumulative" class="${state.mode==='cumulative'?'active':''}">累计</button><button data-mode="daily" class="${state.mode==='daily'?'active':''}">当日</button></div></div><div class="panel-body" style="padding-bottom:0">${legend()}</div><div class="chart-wrap">${renderTrend(seriesFor([o],state.asOf,16,state.mode))}</div><div class="chart-foot"><span>基线 ${o.baselineVersion||'未提供'}</span><span>数据截至 ${a.lastDate||'暂无'}</span></div></section><section class="panel"><div class="panel-head"><div><h2>成本偏差拆解</h2><p>实际成本 − 同产量预期成本</p></div></div><div class="panel-body">${a.comparable?renderCostVariance(items):empty('暂不能拆解偏差','请先补齐实际数据与预期基线。')}<div class="note" style="margin-top:23px">${icon('info')}正值表示成本超出预期；费用仅在一个类别中归集，返工不重复计费。</div></div></section></div><section class="panel" style="margin-bottom:22px"><div class="panel-head"><h2>当天生产快照</h2><a href="#data/${o.id}" class="link">查看完整明细 →</a></div><div class="panel-body"><div class="date-inspect"><label for="day">核查日期</label><input class="control" id="day" type="date" min="${o.start}" max="${state.asOf}" value="${state.day}"></div>${da?`<div class="kv-grid">${kv('当日产量',num(day.quantity)+' 双')}${kv('当日生产成本',money(da.cost,2))}${kv('当日生产毛利',money(da.profit,2))}${kv('当日不良数量',num(day.defects)+' 双')}</div>`:empty('当天暂无生产记录','缺失记录不按零产量或零成本处理。')}</div></section><section class="panel"><div class="panel-head"><div><h2>偏差线索与核查依据</h2><p>以下为数据线索，尚未经过人工原因核验</p></div><a href="#ai/${o.id}" class="link">带入 AI 对话 →</a></div><div class="panel-body"><div class="reason-list">${items.map(i=>`<article class="reason"><h3>${i.name}费用核查</h3><p>实际累计 ${money(i.actual,2)}<br>同期预期 ${money(i.expected,2)}<br>偏差 <span class="${i.delta>0?'negative':'positive'}">${signed(i.delta)}</span></p><a href="#data/${o.id}" class="link">核对每日记录 →</a></article>`).join('')}</div><div class="note" style="margin-top:16px">${icon('info')}当前仅计算生产毛利。经营费用、税费和剩余生产预测尚未接入，预计完工利润暂不提供。</div></div></section>`;}
function kv(label,value){return `<div class="kv"><dt>${label}</dt><dd>${value}</dd></div>`;}
function missingOrder(){return `${empty('未找到这笔订单','请返回监测首页选择有效订单。')}<a class="button" href="#monitor">返回订单监测</a>`;}
function orderOptions(current,all=false){return `${all?option('all','全部订单（24 笔）',current):''}${state.orders.map(o=>option(o.id,o.id+' · '+o.product,current)).join('')}`;}
function dataPage(){const o=selectedOrder();if(!o)return missingOrder();const a=analyzeOrder(o,state.asOf);const rows=a.rows;return `<div class="data-filters"><label for="data-order">核查订单</label><select class="control" id="data-order">${orderOptions(o.id)}</select><a href="#order/${o.id}" class="button">${icon('back')}返回订单分析</a><span class="demo-pill">只读核查</span></div><div class="section-stack"><section class="panel"><div class="panel-head"><h2>订单资料与核算范围</h2>${badge(a.risk)}</div><div class="panel-body"><div class="kv-grid">${kv('客户 / 产品',o.customer+' / '+o.product)}${kv('订单数量 / 演示单价',num(o.quantity)+' 双 / '+money(o.price,2))}${kv('数据截至',a.lastDate||'暂无记录')}${kv('预期基线',o.baselineVersion||'未提供')}</div><div class="note ${!a.comparable?'warning':''}" style="margin-top:20px">${icon('info')}${!a.comparable?'当前订单缺少完整实际数据或预期基线，暂不可计算利润偏差。':'预期与实际按相同已完成产量对照。演示收入按完成数量 × 演示单价计算，不代表真实财务收入确认。'}</div></div></section><section class="panel"><div class="table-top"><h2>每日生产与成本记录 <span class="count">${rows.length} 条</span></h2><span class="muted" style="font-size:10px">金额单位：元 · 数量单位：双</span></div><div class="table-wrap"><table><thead><tr><th>日期</th><th>产量</th><th>不良数量</th><th>材料成本</th><th>人工成本</th><th>能耗成本</th><th>当日毛利</th><th>来源记录</th></tr></thead><tbody>${rows.map(d=>{const da=analyzeOrder({...o,daily:[d]},d.date);return `<tr${d.date===state.day?' style="background:#f3f8ff"':''}><td>${d.date}</td><td>${num(d.quantity)}</td><td>${num(d.defects)}</td>${categories.map(k=>`<td class="${d.costs[k]===null?'negative':''}">${d.costs[k]===null?'待补齐':money(d.costs[k],2)}</td>`).join('')}<td class="${tone(da.profit)}">${money(da.profit,2)}</td><td>${d.source}</td></tr>`;}).join('')}</tbody></table></div>${!rows.length?empty('当前日期前无生产记录','请选择较晚的截至日期。'):''}<div class="panel-footer"><span>缺失字段保留为空，不用 0 替代</span><span>来源：内置合成演示数据</span></div></section><section class="panel"><div class="panel-head"><h2>独立计算过程</h2></div><div class="panel-body"><div class="kv-grid">${kv('累计演示收入',money(a.revenue,2))}${kv('累计生产成本',money(a.cost,2))}${kv('累计生产毛利',money(a.profit,2))}${kv('累计毛利率',pct(a.rate))}</div></div><div class="code-note">演示收入 = 完成产量 × 演示单价 = <code>${num(a.quantity)} × ${money(o.price,2)}</code><br>生产毛利 = 演示收入 − 材料成本 − 人工成本 − 能耗成本<br>预期生产毛利 = 同产量演示收入 × 预期毛利率 = <code>${money(a.expected,2)}</code><br>毛利差额 = 实际生产毛利 − 预期生产毛利 = <code>${signed(a.delta)}</code><br>毛利率偏差 <code>${pp(a.deviation)}</code>；相对下降 <code>${a.decline===null?'不适用':pct(a.decline)}</code></div></section><section class="panel"><div class="panel-head"><h2>来源、版本与待核查项</h2></div><div class="panel-body"><div class="kv-grid">${kv('数据版本',DATA_VERSION)}${kv('规则版本','相对毛利下降 · 演示 v1')}${kv('真实资料接入','尚未接入')}${kv('来源核验','合成数据，仅用于功能演示')}</div><p class="footnote">材料、人工、能耗为互斥归集项。演示不良数量是生产记录字段，不直接折算为额外损失。真实接入前需确认费用范围、产量定义及收入确认依据。</p></div></section></div>`;}
function aiPage(){const o=state.orders.find(x=>x.id===state.chatScope);return `<div class="chat-layout"><aside class="panel chat-context"><h2>分析上下文</h2><label for="chat-scope" class="muted">选择订单范围</label><select id="chat-scope" class="control">${orderOptions(state.chatScope,true)}</select><p>对话将关联选中的订单、日期和数据版本，方便后续追溯回答依据。</p><div class="context-line"><span>数据截至</span><strong>${state.asOf}</strong></div><div class="context-line"><span>订单范围</span><strong>${o?'单笔订单':'全部 24 笔'}</strong></div><div class="context-line"><span>数据类型</span><strong>合成演示数据</strong></div><div class="context-line"><span>服务状态</span><strong>未接入</strong></div><div class="help-block">${icon('info')} 接入后，成本与利润由计算服务提供，AI 负责解释数据、列出依据和提出核查建议。</div></aside><section class="panel chat-panel"><div class="chat-center"><div class="ai-orb">${icon('spark')}</div><h2>让订单数据更容易理解</h2><p>从一笔订单开始，了解利润变化与成本偏差。<br>当前为对话界面预览，AI 服务待接入。</p><div class="prompts"><button class="prompt" data-prompt="哪些订单今天需要优先关注？">哪些订单需要优先关注？<span>查看多订单风险与利润偏差</span></button><button class="prompt" data-prompt="这笔订单与预期相比少赚了多少？">与预期相比少赚了多少？<span>理解实际与计划之间的差距</span></button><button class="prompt" data-prompt="利润差距主要体现在哪些成本项目？">利润差距体现在哪些成本？<span>定位材料、人工与能耗偏差</span></button><button class="prompt" data-prompt="还有哪些数据需要补充才能判断原因？">还需要补充哪些数据？<span>识别缺失记录与待核查信息</span></button></div></div><form class="composer" id="chat-form"><div class="chat-status" role="status">${esc(state.chatStatus)}</div><div class="composer-box"><textarea id="chat-input" aria-label="向 AI 提问" placeholder="输入关于订单利润或生产数据的问题…" maxlength="2000">${esc(state.chatDraft)}</textarea><div class="composer-actions"><span>AI 接口待接入 · 当前不会发送数据</span><button class="button primary" type="submit">${icon('send')}发送</button></div></div><p class="footnote">后续回答将展示结论、引用依据和待确认项。模型部署方式由团队进一步确定。</p></form></section></div>`;}
function render(){const content=state.loading?'<div class="loading">正在载入订单数据…</div>':state.error?`${empty('数据载入失败',esc(state.error))}<button class="button" data-action="refresh">重新载入</button>`:state.route==='monitor'?monitoring():state.route==='order'?detail():state.route==='data'?dataPage():aiPage();app.innerHTML=shell(content);document.title=titles[state.route][0]+' · 企盈智擎';}
async function refresh(notify=false){state.loading=true;state.error=null;render();try{state.orders=await getOrders();parseRoute();state.loading=false;render();if(notify)toast('已重新载入演示数据，数据截至 '+END);}catch(e){state.loading=false;state.error=e.message;render();}}
app.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){switch(a.dataset.action){case'refresh':refresh(true);break;case'reset':Object.assign(state,{search:'',customer:'',status:'生产中',risk:'',page:1,asOf:END,period:16,inspected:null});render();break;case'alerts':state.risk='严重';state.page=1;render();break;case'clear-day':state.inspected=null;render();break;}return;}const page=e.target.closest('[data-page]');if(page){state.page=+page.dataset.page;render();return;}const mode=e.target.closest('[data-mode]');if(mode){state.mode=mode.dataset.mode;render();return;}const day=e.target.closest('[data-day]');if(day){if(state.route==='order')state.day=day.dataset.day;else state.inspected=day.dataset.day;render();return;}const prompt=e.target.closest('[data-prompt]');if(prompt){state.chatDraft=prompt.dataset.prompt;state.chatStatus='';render();document.querySelector('#chat-input').focus();}});
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-day]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
app.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;state.search=e.target.value;state.page=1;render();const input=document.querySelector('#search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}if(e.target.id==='chat-input')state.chatDraft=e.target.value;});
app.addEventListener('change',e=>{const {id,value}=e.target;if(['customer','status','risk','sort','period'].includes(id)){state[id]=id==='period'?+value:value;state.page=1;state.inspected=null;render();}if(id==='asOf'){if(!value||value<'2026-10-01'||value>END){toast('请选择 2026-10-01 至 '+END+' 的演示日期');render();return;}state.asOf=value;state.day=value;state.inspected=null;state.page=1;render();}if(id==='day'){if(!value||value<'2026-10-01'||value>state.asOf){toast('请选择有效核查日期');render();return;}state.day=value;render();}if(id==='data-order')go('#data/'+value);if(id==='chat-scope'){state.chatScope=value;state.chatStatus='';render();}});
app.addEventListener('submit',async e=>{if(e.target.id!=='chat-form')return;e.preventDefault();if(!state.chatDraft.trim()){toast('请先输入一个问题');return;}try{await sendChat({orderIds:state.chatScope==='all'?state.orders.map(o=>o.id):[state.chatScope],dateRange:['2026-10-01',state.asOf],dataVersion:DATA_VERSION,message:state.chatDraft});}catch(error){state.chatStatus=error.message;render();}});
window.addEventListener('hashchange',()=>{parseRoute();render();window.scrollTo({top:0,behavior:'instant'});});
parseRoute();refresh();
